import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 기본 크기 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const COLUMNS = `
  leave_grant_rule_id AS "leaveGrantRuleId",
  rule_name AS "ruleName",
  service_year_from AS "serviceYearFrom",
  service_year_to AS "serviceYearTo",
  base_days AS "baseDays",
  additional_days AS "additionalDays",
  additional_condition AS "additionalCondition",
  use_status AS "useStatus"
`;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_LEAVE_GRANT_RULE', message);
}

function toNumber(value: unknown, required: boolean, label: string, integer: boolean): number | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      throw invalid(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  let result: number;
  if (typeof value === 'number') {
    result = value;
  } else if (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(value.trim())) {
    result = Number(value.trim());
  } else {
    throw invalid(label + '은(는) 숫자로 입력해 주세요.');
  }
  if (!Number.isFinite(result)) {
    throw invalid(label + '은(는) 숫자로 입력해 주세요.');
  }
  if (integer && !Number.isInteger(result)) {
    throw invalid(label + '은(는) 정수로 입력해 주세요.');
  }
  if (result < 0) {
    throw invalid(label + '은(는) 0 이상이어야 합니다.');
  }
  return result;
}

function optionalText(value: unknown, max: number, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw invalid(label + '을(를) ' + max + '자 이내의 글자로 입력해 주세요.');
  }
  return value;
}

function parseRule(data: Record<string, unknown>) {
  const ruleName = data['ruleName'];
  if (typeof ruleName !== 'string' || ruleName.trim() === '' || ruleName.length > 100) {
    throw invalid('기준명을 100자 이내로 입력해 주세요.');
  }
  const serviceYearFrom = toNumber(data['serviceYearFrom'], true, '근속연수 시작', true);
  const serviceYearTo = toNumber(data['serviceYearTo'], false, '근속연수 종료', true);
  const baseDays = toNumber(data['baseDays'], true, '기본 일수', false);
  const additionalDays = toNumber(data['additionalDays'], false, '가산 일수', false);
  const additionalCondition = optionalText(data['additionalCondition'], 500, '가산 조건');
  const useStatus = data['useStatus'];
  if (useStatus !== '사용' && useStatus !== '미사용') {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  if (serviceYearTo !== null && serviceYearFrom !== null && serviceYearTo <= serviceYearFrom) {
    throw invalid('근속연수 종료는 시작보다 커야 합니다.');
  }
  return {
    ruleName: ruleName.trim(),
    serviceYearFrom,
    serviceYearTo,
    baseDays,
    additionalDays,
    additionalCondition,
    useStatus,
  };
}

function parseId(value: string | undefined): number {
  if (value === undefined || !/^\d+$/.test(value)) {
    throw new ApiError(404, 'LEAVE_GRANT_RULE_NOT_FOUND', '연차 생성 기준을 찾을 수 없습니다.');
  }
  return Number(value);
}

@Controller('api/v1')
export class FnSfr01901Controller {
  @Get('/leave-grant-rules')
  async listLeaveGrantRules(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const q: Record<string, unknown> = checks.queryOf(req.query);
    const pageRaw = Number(q['page'] ?? 0);
    const sizeRaw = Number(q['size'] ?? DEFAULT_SIZE);
    const page = Number.isInteger(pageRaw) && pageRaw >= 0 ? pageRaw : 0;
    let size = Number.isInteger(sizeRaw) && sizeRaw > 0 ? sizeRaw : DEFAULT_SIZE;
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT ${COLUMNS} FROM leave_grant_rule ORDER BY leave_grant_rule_id DESC LIMIT :size OFFSET :offset`,
        { size, offset: page * size },
      );
      const counted = await db.query('SELECT CAST(COUNT(*) AS integer) AS "total" FROM leave_grant_rule', {});
      const total = Number(counted[0]?.total ?? 0);
      return { items, page, size, total };
    });
  }

  @Post('/leave-grant-rules')
  @HttpCode(200)
  async createLeaveGrantRule(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const v = parseRule(data);
    return transaction(async (db) => {
      const rows = await db.query(
        `INSERT INTO leave_grant_rule (
           rule_name, service_year_from, service_year_to, base_days,
           additional_days, additional_condition, use_status, created_at, updated_at
         ) VALUES (
           :ruleName, CAST(:serviceYearFrom AS integer), CAST(:serviceYearTo AS integer), CAST(:baseDays AS numeric),
           CAST(:additionalDays AS numeric), :additionalCondition, :useStatus, now(), now()
         ) RETURNING leave_grant_rule_id AS "leaveGrantRuleId"`,
        v,
      );
      return { leaveGrantRuleId: Number(rows[0].leaveGrantRuleId) };
    });
  }

  @Put('/leave-grant-rules/:leaveGrantRuleId')
  async updateLeaveGrantRule(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const id = parseId(req.params['leaveGrantRuleId']);
    const data = checks.inputOf(req.body);
    const v = parseRule(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT leave_grant_rule_id FROM leave_grant_rule WHERE leave_grant_rule_id = :id',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'LEAVE_GRANT_RULE_NOT_FOUND', '연차 생성 기준을 찾을 수 없습니다.');
      }
      await db.execute(
        `UPDATE leave_grant_rule SET
           rule_name = :ruleName,
           service_year_from = CAST(:serviceYearFrom AS integer),
           service_year_to = CAST(:serviceYearTo AS integer),
           base_days = CAST(:baseDays AS numeric),
           additional_days = CAST(:additionalDays AS numeric),
           additional_condition = :additionalCondition,
           use_status = :useStatus,
           updated_at = now()
         WHERE leave_grant_rule_id = :id`,
        { ...v, id },
      );
      return { leaveGrantRuleId: id };
    });
  }

  @Delete('/leave-grant-rules/:leaveGrantRuleId')
  async deleteLeaveGrantRule(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const id = parseId(req.params['leaveGrantRuleId']);
    return transaction(async (db) => {
      const count = await db.execute(
        'DELETE FROM leave_grant_rule WHERE leave_grant_rule_id = :id',
        { id },
      );
      if (count === 0) {
        throw new ApiError(404, 'LEAVE_GRANT_RULE_NOT_FOUND', '연차 생성 기준을 찾을 수 없습니다.');
      }
      return {};
    });
  }
}

