import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Mode =
  | { type: 'create' }
  | { type: 'detail'; row: Row }
  | { type: 'edit'; row: Row }
  | { type: 'delete'; row: Row }
  | null;

const STATUS_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];

const EMPTY_FORM: Row = {
  ruleName: '',
  serviceYearFrom: '',
  serviceYearTo: '',
  baseDays: '',
  additionalDays: '',
  additionalCondition: '',
  useStatus: '사용',
};

export default function FnSfr01901Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [statusFilter, setStatusFilter] = useState('');
  const [appliedStatus, setAppliedStatus] = useState('');
  const [mode, setMode] = useState<Mode>(null);
  const [form, setForm] = useState<Row>(EMPTY_FORM);
  const size = 20;

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/leave-grant-rules', role, undefined, { page, size }),
    [page, role],
  );

  const items = (data?.items ?? []).filter((r) => appliedStatus === '' || r['useStatus'] === appliedStatus);
  const usedCount = (data?.items ?? []).filter((r) => r['useStatus'] === '사용').length;
  const unusedCount = (data?.items ?? []).filter((r) => r['useStatus'] === '미사용').length;

  const setField = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const openCreate = () => {
    setForm(EMPTY_FORM);
    setMode({ type: 'create' });
  };

  const openEdit = (row: Row) => {
    setForm({
      ruleName: row['ruleName'] ?? '',
      serviceYearFrom: row['serviceYearFrom'] ?? '',
      serviceYearTo: row['serviceYearTo'] ?? '',
      baseDays: row['baseDays'] ?? '',
      additionalDays: row['additionalDays'] ?? '',
      additionalCondition: row['additionalCondition'] ?? '',
      useStatus: row['useStatus'] ?? '사용',
    });
    setMode({ type: 'edit', row });
  };

  const isBlank = (v: unknown) => v === undefined || v === null || String(v).trim() === '';

  const checkForm = () => {
    if (isBlank(form['ruleName'])) {
      throw new Error('기준명을 입력해 주세요.');
    }
    if (isBlank(form['serviceYearFrom'])) {
      throw new Error('근속연수 시작을 입력해 주세요.');
    }
    if (isBlank(form['baseDays'])) {
      throw new Error('기본 일수를 입력해 주세요.');
    }
    if (isBlank(form['useStatus'])) {
      throw new Error('사용 여부를 선택해 주세요.');
    }
  };

  const body = (): Row => ({
    ruleName: form['ruleName'],
    serviceYearFrom: form['serviceYearFrom'],
    serviceYearTo: isBlank(form['serviceYearTo']) ? undefined : form['serviceYearTo'],
    baseDays: form['baseDays'],
    additionalDays: isBlank(form['additionalDays']) ? undefined : form['additionalDays'],
    additionalCondition: isBlank(form['additionalCondition']) ? undefined : form['additionalCondition'],
    useStatus: form['useStatus'],
  });

  const submitCreate = async () => {
    checkForm();
    await call('POST', '/leave-grant-rules', role, body());
    notify('연차 생성 기준을 등록했습니다.');
    setMode(null);
    reload();
  };

  const submitEdit = async (row: Row) => {
    checkForm();
    await call('PUT', '/leave-grant-rules/' + String(row['leaveGrantRuleId']), role, body());
    notify('연차 생성 기준을 수정했습니다.');
    setMode(null);
    reload();
  };

  const submitDelete = async (row: Row) => {
    await call('DELETE', '/leave-grant-rules/' + String(row['leaveGrantRuleId']), role);
    notify('연차 생성 기준을 삭제했습니다.');
    setMode(null);
    reload();
  };

  const formFields = (
    <>
      <Field label='기준명' required>
        <TextInput value={form['ruleName']} onChange={(v) => setField('ruleName', v)} />
      </Field>
      <Field label='근속연수 시작' required hint='이상(년)'>
        <NumberInput value={form['serviceYearFrom']} onChange={(v) => setField('serviceYearFrom', v)} />
      </Field>
      <Field label='근속연수 종료' hint='미만(년), 비우면 상한 없음'>
        <NumberInput value={form['serviceYearTo']} onChange={(v) => setField('serviceYearTo', v)} />
      </Field>
      <Field label='기본 일수' required>
        <NumberInput value={form['baseDays']} onChange={(v) => setField('baseDays', v)} />
      </Field>
      <Field label='가산 일수'>
        <NumberInput value={form['additionalDays']} onChange={(v) => setField('additionalDays', v)} />
      </Field>
      <Field label='가산 조건' wide>
        <TextInput
          multiline
          value={form['additionalCondition']}
          onChange={(v) => setField('additionalCondition', v)}
        />
      </Field>
      <Field label='사용 여부' required>
        <Select
          value={form['useStatus']}
          onChange={(v) => setField('useStatus', v)}
          options={STATUS_OPTIONS}
          placeholder='선택'
        />
      </Field>
    </>
  );

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>기준 현황</h2>
        <Tiles
          items={[
            ['전체 기준', <Num value={data?.total ?? 0} />],
            ['사용 (현재 쪽)', <Num value={usedCount} />],
            ['미사용 (현재 쪽)', <Num value={unusedCount} />],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>연차 생성 기준</h2>
        <Filters
          onSearch={() => setAppliedStatus(statusFilter)}
          onReset={() => {
            setStatusFilter('');
            setAppliedStatus('');
          }}
        >
          <Field label='사용 여부'>
            <Select value={statusFilter} onChange={setStatusFilter} options={STATUS_OPTIONS} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type='button' onClick={openCreate}>
            기준 등록
          </button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={items}
          empty='등록된 연차 생성 기준이 없습니다.'
          onRowClick={(row) => setMode({ type: 'detail', row })}
          columns={[
            { key: 'ruleName', label: '기준명' },
            { key: 'serviceYearFrom', label: '근속연수 시작', render: (r) => <Num value={r['serviceYearFrom']} /> },
            { key: 'serviceYearTo', label: '근속연수 종료', render: (r) => (r['serviceYearTo'] == null ? '상한 없음' : <Num value={r['serviceYearTo']} />) },
            { key: 'baseDays', label: '기본 일수', render: (r) => <Num value={r['baseDays']} /> },
            { key: 'additionalDays', label: '가산 일수', render: (r) => <Num value={r['additionalDays']} /> },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
          ]}
        />
        <Pager page={page} size={size} total={data?.total ?? 0} onPage={setPage} />
      </section>

      {mode?.type === 'create' ? (
        <Drawer title='연차 생성 기준 등록' onClose={() => setMode(null)}>
          <Form onSubmit={submitCreate} submit='등록'>
            {formFields}
          </Form>
        </Drawer>
      ) : null}

      {mode?.type === 'detail' ? (
        <Drawer title='연차 생성 기준 상세' onClose={() => setMode(null)}>
          <Pairs
            items={[
              ['기준명', String(mode.row['ruleName'] ?? '')],
              ['근속연수 시작', <Num value={mode.row['serviceYearFrom']} />],
              ['근속연수 종료', mode.row['serviceYearTo'] == null ? '상한 없음' : <Num value={mode.row['serviceYearTo']} />],
              ['기본 일수', <Num value={mode.row['baseDays']} />],
              ['가산 일수', <Num value={mode.row['additionalDays']} />],
              ['가산 조건', String(mode.row['additionalCondition'] ?? '')],
              ['사용 여부', <Badge value={mode.row['useStatus']} />],
            ]}
          />
          <Band>
            <button type='button' onClick={() => openEdit(mode.row)}>
              수정
            </button>
            <button type='button' onClick={() => setMode({ type: 'delete', row: mode.row })}>
              삭제
            </button>
          </Band>
        </Drawer>
      ) : null}

      {mode?.type === 'edit' ? (
        <Drawer title='연차 생성 기준 수정' onClose={() => setMode(null)}>
          <Form onSubmit={() => submitEdit(mode.row)} submit='저장'>
            {formFields}
          </Form>
        </Drawer>
      ) : null}

      {mode?.type === 'delete' ? (
        <Drawer title='연차 생성 기준 삭제' onClose={() => setMode(null)}>
          <Form
            danger
            submit='삭제'
            onSubmit={() => submitDelete(mode.row)}
            note={'다음 기준을 삭제합니다: ' + String(mode.row['ruleName'] ?? '')}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
